{
  "trailers": [
    {
      "title": "Betrayed at the Altar",
      "moment_ids": ["M003", "M011", "M012"],
      "hook": "Gerald callously says he changed his mind, and Juliana cries out that he swore he loved her.",
      "cliffhanger": "The Bearded Stranger drops to one knee before Lady Juliana, offering a silver ring as she gazes down at him with tears and a trembling smile of hope.",
      "why": "Starts with devastating betrayal, pivots to a mysterious rescuer, and ends on a marriage proposal that leaves her fate hanging."
    },
    {
      "title": "The Scarred Soldier's Secret",
      "moment_ids": ["M038", "M074", "M075"],
      "hook": "Alexander removes his shirt, revealing a torso covered in jagged battle scars, and Juliana whispers 'Dear God' in horror.",
      "cliffhanger": "Alexander realizes his mother is a prisoner and coldly decides to let his enemies believe he is dead a little longer.",
      "why": "Opens with a shocking physical reveal, then exposes his hidden ducal identity and ends on a dangerous decision to stay dead."
    },
    {
      "title": "Poison in the Manor",
      "moment_ids": ["M090", "M091", "M092"],
      "hook": "The Duchess chokes and spasms; Juliana rushes to prepare an antidote and tells Prudence she can try to save her.",
      "cliffhanger": "Juliana is trapped with an unfinished cure as the door latch turns and the door cracks open.",
      "why": "Begins with a life-or-death medical emergency, builds tension with approaching footsteps, and cuts on the door opening before she can finish the cure."
    },
    {
      "title": "The Witch's Trial",
      "moment_ids": ["M124", "M161", "M164"],
      "hook": "Catherine swings the glowing branding iron toward Juliana's face, stopping inches from her eye as she recoils in terror.",
      "cliffhanger": "The cathedral doors explode in a fireball, and armed silhouettes emerge through the smoke as Juliana turns in awe.",
      "why": "Opens with a visceral threat of torture, escalates to public humiliation at the wedding, and ends on a fiery rescue with unknown figures emerging."
    }
  ]
}
